from playwright.sync_api import sync_playwright
with sync_playwright() as p:
 b=p.chromium.launch(headless=True,args=['--no-sandbox']);page=b.new_page(viewport={'width':1366,'height':768});errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto('http://localhost:3000');page.wait_for_selector('#playAdventure');page.click('#playAdventure');page.wait_for_function("state==='play'")
 result=page.evaluate('''()=>{const results=[];function simulation(st,w,id){stage=st;wave=w;const e={x:400,y:200,baseX:400,speed:70+st*13,pattern:0,age:0,id};let up=0,maxStep=0;const path=[];for(let i=0;i<900;i++){const previous=e.y;e.age+=1/60;e.y+=e.speed/60;Encounters.move(e,1/60);if(e.y<previous)up++;maxStep=Math.max(maxStep,Math.abs(e.y-previous));path.push(e.y)}return{up,maxStep,path,amplitude:e.verticalDrift.amplitude}}for(let st=0;st<5;st++)results.push(simulation(st,3,.321));const intro=simulation(0,1,.321),again=simulation(4,3,.321),different=simulation(4,3,.654);return{intro:intro.amplitude===0&&intro.up===0,ascending:results[4].up>0,progression:results.every((r,i)=>!i||r.amplitude>results[i-1].amplitude),bounded:results.every(r=>r.maxStep<8),seeded:JSON.stringify(results[4].path)===JSON.stringify(again.path),varied:JSON.stringify(again.path)!==JSON.stringify(different.path),metrics:results.map(r=>({up:r.up,amplitude:r.amplitude,maxStep:r.maxStep}))}}''');assert all(result[k] for k in ['intro','ascending','progression','bounded','seeded','varied']),result
 assert not errors,errors;print('OK : dérive verticale aléatoire fluide, vraies remontées, amplitude progressive, trajectoires variées et reproductibles, première vague inchangée.',result['metrics']);b.close()
